void selection_sort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[m]) m = j;
        }
        int t = a[i];
        a[i] = a[m];
        a[m] = t;
    }
}

void selection_sort(int a[], int n) {
    int i = 0;
    while (i < n - 1) {
        int m = i;
        int j = i + 1;
        while (j < n) {
            if (a[j] < a[m]) m = j;
            j++;
        }
        int t = a[i];
        a[i] = a[m];
        a[m] = t;
        i++;
    }
}

void selection_sort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[m]) m = j;
        }
        if (m != i) {
            int t = a[m];
            a[m] = a[i];
            a[i] = t;
        }
    }
}

